def step(s,a):
    c,r,bs=s; bs=[list(b) for b in bs]
    if a=='R':
        if c==5:return s
        nc=c+1
        # push contiguous chain beginning p=nc (block right of old body)
        rowbs=sorted([b for b in bs if b[1]==r],key=lambda b:b[0])
        # push any block at p=nc and adjacent chain, max4
        if any(b[0]==nc for b in rowbs):
            for b in sorted(rowbs,key=lambda b:-b[0]):
                if b[0]>=nc: b[0]=min(4,b[0]+1)
        c=nc
    elif a=='L':
        if c==0:return s
        nc=c-1
        for b in bs:
            if b[1]==r:
                if b[0]>=nc:b[0]=max(0,b[0]-1)
                elif b[0]==nc-1:b[0]=min(4,b[0]+1)
        c=nc
    elif a in 'UD':
        nr=r+(-1 if a=='U' else 1)
        if not 0<=nr<=4:return s
        # blocks in current row and p>=c move
        for b in bs:
            if b[1]==r and b[0]>=c:b[1]=nr
        r=nr
    # remove blocks overlapped by body p=c in current row, and collisions all involved
    bs=[b for b in bs if not (b[1]==r and b[0]==c)]
